#[derive(Debug, Clone)]
struct Complex {
    real: i32,
    imag: i32,
}

#[verus::spec]
fn real_if_close(arr: Vec<Complex>, tol: i32) -> Vec<Complex> {
    // Define the machine epsilon
    const EPSILON: i32 = 2;

    // Requires clause to ensure the tolerance is non-negative
    #[verus::requires(tol >= 0)]
    // Ensures clause to specify the output conditions
    #[verus::ensures(
        // The output is either the same as the input or has all imaginary parts set to zero
        (arr.iter().all(|c| (c.imag.abs() <= tol * EPSILON)) ==> 
            (result.iter().all(|c| c.imag == 0) && result.len() == arr.len())) &&
        (!arr.iter().all(|c| (c.imag.abs() <= tol * EPSILON)) ==> 
            (result == arr))
    )]
    // Invariant to maintain the state of the array during iteration
    #[verus::invariant(
        // For all elements in the array, the imaginary part is checked against the tolerance
        forall(|i: usize| i < arr.len() ==> (arr[i].imag.abs() <= tol * EPSILON) == (result[i].imag == 0))
    )]
    // Decreases clause to ensure termination
    #[verus::decreases(arr.len())]
    let result = if arr.iter().all(|c| (c.imag.abs() <= tol * EPSILON)) {
        // Create a new array with imaginary parts set to zero
        arr.iter().map(|c| Complex { real: c.real, imag: 0 }).collect()
    } else {
        // Return the input array unchanged
        arr
    };

    result
}

